To modify the code to use a **shared base class `Quantity`** for `Temperature`, `Length`, and `Mass`, we can create a base class `Quantity` that contains common functionality, such as the `value` and `unit` attributes, and possibly some common methods like `__str__` or `__repr__`.

Here's the modified code with the `Quantity` base class:

```python
class Quantity:
    def __init__(self, value, unit):
        self.value = value
        self.unit = unit

    def __str__(self):
        return f"{self.value} {self.unit}"


class Temperature(Quantity):
    def to_fahrenheit(self):
        if self.unit == "C":
            return (self.value * 9/5) + 32
        elif self.unit == "F":
            return self.value
        else:
            raise ValueError("Invalid temperature unit")

    def to_celsius(self):
        if self.unit == "C":
            return self.value
        elif self.unit == "F":
            return (self.value - 32) * 5/9
        else:
            raise ValueError("Invalid temperature unit")


class Length(Quantity):
    def to_inches(self):
        if self.unit == "cm":
            return self.value / 2.54
        elif self.unit == "in":
            return self.value
        else:
            raise ValueError("Invalid length unit")

    def to_cm(self):
        if self.unit == "cm":
            return self.value
        elif self.unit == "in":
            return self.value * 2.54
        else:
            raise ValueError("Invalid length unit")


class Mass(Quantity):
    def to_pounds(self):
        if self.unit == "kg":
            return self.value * 2.20462
        elif self.unit == "lb":
            return self.value
        else:
            raise ValueError("Invalid mass unit")

    def to_kg(self):
        if self.unit == "kg":
            return self.value
        elif self.unit == "lb":
            return self.value / 2.20462
        else:
            raise ValueError("Invalid mass unit")


# Test the code
temp = Temperature(37, "C")
print(temp.to_fahrenheit())  # Output: 98.6

length = Length(180, "cm")
print(length.to_inches())    # Output
